        "id": "KIM-TYT-K06-T08-S02",
        "question": "$2H_2 \\ (g) + O_2 \\ (g) \\rightarrow 2H_2O \\ (g)$\nYukarıdaki tepkimeye göre kapalı bir kaba **$4 \\ mol$ $H_2$** gazı ve **$4 \\ mol$ $O_2$** gazı konarak tam verimle tepkime başlatılıyor.\nTepkime sonunda hangi gazdan kaç mol **ARTAR**?\n(Önce sınırlayıcıyı bulun).",
