        "difficulty": "medium",
        "solution": "$CO_2$'deki sabit oran $\\frac{m_C}{m_O} = \\frac{12}{32}$'dir (Yani 12 gram C'ye karşılık 32 gram Oksijen lazımdır).\n\"Eşit kütle\" dediği için Büyük olana göre kaba madde koyalım. Kapta 32 gram C ve 32 gram O olsun (Başlangıç).\nOksijenin tamamı (32g) harcanır (Biter).\nKarbonun ise sadece 12 gramı harcanır. Kapta $32 - 12 = 20 \\ gram$ Karbon (C) ARTAR.\nSoru: \"Karbon, alınan kütlesinin yüzde kaçı arttı?\"\nBaşlangıçta 32 gram almıştık, 20 gramı arttı.\nOran = $20 / 32 = 5 / 8$. Yüzde olarak = %62.5 Karbon (C) artar. (B)."
