        "question": "$A + 3B \\rightarrow 2C$\nTepkimesi için bir kaba 2'şer mol A ve B konuyor.\nTepkime %50 verimle gerçekleştiğinde kapta toplam kaç mol madde (gaz) bulunur?\n(Önce sınırlayıcıyı bulun, sonra %50'sini harcayın).",
