        "id": "KIM-TYT-K06-T13-S10",
        "question": "$3.2 \\ gram$ Metan ($CH_4$) gazı, $0.6 \\ mol$ Oksijen ($O_2$) gazı ile;\n$CH_4 + 2O_2 \\rightarrow CO_2 + 2H_2O$\ntepkimesine göre tam verimle yakılıyor.\nTepkime sonunda artan gazın kütlesi kaç gramdır?\n(C = 12, H = 1, O = 16)",
