        "id": "KIM-TYT-K06-T14-S04",
        "question": "$N_2 \\ (g) + 3H_2 \\ (g) \\rightarrow 2NH_3 \\ (g)$\nNormal şartlar altında 44.8 Litre hacim kaplayan bir $N_2$ ve $H_2$ gaz karışımı tam verimle tepkimeye sokulduğunda, kapta hiç gaz artmadığı (ikisinin de tamamen tükendiği) görülüyor.\nBuna göre kapta başlangıçta kaç gram Azot ($N_2$) gazı vardır?\n(N = 14, H = 1)",
