        "correctAnswer": "D",
        "difficulty": "medium",
        "solution": "$A_2B_3$ bileşiğinin %70'i A ise, %30'u B'dir.\nKütlece oran $\\frac{m_A}{m_B} = \\frac{70}{30} = \\frac{7}{3}$.\n$A_2B_3$'te 2 tane A ve 3 tane B var.\n$\\frac{2 \\times A}{3 \\times B} = \\frac{7}{3}$.\n3'ler sadeleşir. $2 \\times A = 7 \\times B \\Rightarrow \\frac{A}{B} = \\frac{7}{2}$ (Atom ağırlıkları oranı).\nYeni bileşik $AB_2$.\nBunda 1 tane A, 2 tane B var.\nKütlece Oran = $\\frac{1 \\times A}{2 \\times B} = \\frac{1 \\times 7}{2 \\times 2} = \\frac{7}{4}$. (D şıkkı 7/8 diyor, B şıkkı 7/4 diyor).\nEvet, B şıkkı 7/4. Cevap B. (Düzeltme: B)."
