        "correctAnswer": "B",
        "difficulty": "medium",
        "solution": "Kütle (m) sabittir. $d = m / V$.\nBaşlangıç molü = 5V hacim kaplasın.\nBitiş molü = 3V hacim kaplar.\nBaşlangıç Özkütlesi ($d_1$) = $m / 5$.\nBitiş Özkütlesi ($d_2$) = $m / 3$.\nArtış miktarı: $m/3 - m/5 = 2m/15$.\nYüzde Artış = (Artış / İlk Değer) $\\times 100$\n$(2m/15) / (m/5) = (2/15) \\times (5/1) = 10/15 = 2/3$.\nYüzde olarak: $2/3 = \\%66.6...$ (Yani %66.6 artar). (B)."
