        "correctAnswer": "B",
        "difficulty": "medium",
        "solution": "$CaS$ MA'sı = $40 + 32 = 72 \\ g/mol$.\nOluşan 36 gram CaS olduğuna göre, (72'nin tam yarısı) demek ki 0.5 moldür.\n1 mol CaS oluşurken $\\rightarrow$ 40g Ca ve 32g S gerekir.\n0.5 mol oluşurken $\\rightarrow$ 20g Ca ve 16g S harcanır. (Harcananlar bunlardır).\nSoru \"Eşit kütlede alındı\" diyor. Harcananlardan BÜYÜK olanına göre alınmıştır. İkisinden de 20'şer gram alınmıştır.\nCa = 20g alındı, 20g harcandı (Bitti).\nS = 20g alındı, 16g harcandı, $20 - 16 = 4 \\ gram$ S (Kükürt) ARTTI. (B)."
