        "solution": "8.96 L = 0.4 mol $C_3H_4$.\nYanma: $C_3H_4 + 4 O_2 \\rightarrow 3 CO_2 + 2 H_2O$.\n$1 \\ mol$ için $4 \\ mol \\ O_2$ lazım.\n$0.4 \\ mol$ için $0.4 \\times 4 = 1.6 \\ mol \\ O_2$ lazım.\n1.6 mol $O_2$ hacmi = $1.6 \\times 22.4 = 35.84 \\ Litre \\ O_2$ gereklidir.\nHavanın %20'si (Yani 5'te 1'i) oksijendir.\nGereken Hava = $35.84 \\times 5 = 179.2 \\ Litre$ Hava. (D)."
