        "question": "$1.505 \\times 10^{23}$ tane molekül içeren $CH_4$ gazının kütlesi ile, aynı kütleye sahip $He$ (Helyum) gazının NŞA'daki hacmi kaç Litredir?\n(C=12, H=1, He=4, $N_A = 6.02 \\times 10^{23}$)",
