        "question": "Kütlece birleşme oranı $\\frac{m_{Fe}}{m_O} = \\frac{7}{3}$ olan $Fe_2O_3$ bileşiğinden 40 gram elde edebilmek için, içinde en fazla %20 oranında safsızlık (kirlilik) barındıran Demir (Fe) filizinden en az kaç gram alınmalıdır?",
