        "difficulty": "medium",
        "solution": "Mg kütlesi 20g idi, 30g oldu. Demek ki 10 gram Oksijen (O) bağlandı.\nEğer %100 yansaydı ne olurdu?\nDenklem: 24 gram Mg yandığında 16 gram Oksijen bağlar.\n20 gram Mg yandığında X gram bağlar.\n$X = (20 \\times 16) / 24 = 320 / 24 = 13.33 \\ gram$ Oksijen bağlaması gerekirdi.\nFakat gerçekte 10 gram bağlamış.\nVerim = $(10 / 13.33) \\times 100 = 10 / (40/3) = 30/40 = 3/4 = \\%75$. (C)."
