        "solution": "I. Bileşik = $XY$. %60 X ise %40 Y'dir.\nYani $\\frac{X}{Y} = \\frac{60}{40} = \\frac{3}{2}$ (Atom ağırlıkları oranıdır, çünkü basit formül 1'e 1).\nII. Bileşik = $X_2Y_3$.\nKütleleri bulalım: $X_2 = 2 \\times 3 = 6$. $Y_3 = 3 \\times 2 = 6$.\nYani II. bileşikte kütlece X ve Y EŞİTTİR (6'ya 6).\nDolayısıyla II. bileşikte kütlece %50 X, %50 Y bulunur!\nAaa şıklarda %50 (E şıkkı) var! Ben C demişim.\nHesap hatası yok. $X=3$, $Y=2$.\n$X_2 = 6$. $Y_3 = 6$. Eşit kütle = %50. Doğru cevap E'dir.\n(Düzeltme: Cevap E)."
