        "question": "A ve B elementlerinden oluşan iki farklı bileşikten;\nI. bileşikte kütlece %30 A elementi bulunmaktadır.\nII. bileşikte A ile B'nin kütlece birleşme oranı ($m_A / m_B$) 1/4'tür.\nI. bileşiğin formülü $A_2B_3$ olduğuna göre, II. bileşiğin formülü aşağıdakilerden hangisidir?",
