        "difficulty": "hard",
        "solution": "Karışım = 11.2 L = 0.5 mol.\n$x \\ mol \\ CO$ + $y \\ mol \\ CO_2$ = 0.5 mol.\n$28x + 44y = 18$ gram.\nÇözüm: $y = 0.5 - x$ koyalım.\n$28x + 44(0.5 - x) = 18$\n$28x + 22 - 44x = 18 \\Rightarrow 16x = 4 \\Rightarrow x = 0.25 \\ mol \\ CO$.\n$y = 0.25 \\ mol \\ CO_2$.\nCO yakılarak tamamen $CO_2$'ye dönüştürülüyor:\n$CO + 1/2 O_2 \\rightarrow CO_2$.\n0.25 mol CO yanarsa 0.25 mol daha $CO_2$ üretir.\nKapta zaten 0.25 mol $CO_2$ vardı. Yeni gelenle beraber $0.25 + 0.25 = 0.5 \\ mol$ $CO_2$ olur. (A)."
