        "question": "$A \\rightarrow B + 2C$ tepkimesine göre 2 mol A maddesi parçalanmaktadır.\nKapalı bir kapta gerçekleşen tepkime süresince kaptaki;\nI. Toplam Kütle\nII. Toplam Molekül Sayısı\nIII. Özkütle (Sabit hacimli ise)\nniceliklerinden hangileri kesinlikle **SABİT** kalır?",
