        "id": "KIM-TYT-K06-T25-S02",
        "question": "Bir miktar $XCO_3$ katısı ısıtıldığında tam verimle;\n$XCO_3(k) \\rightarrow XO(k) + CO_2(g)$\ntepkimesine göre ayrışıyor.\nTepkime sonunda kapta 22 gram $CO_2$ gazı oluşurken, katı kütlesinde 22 gramlık bir azalma olduğu gözlemleniyor. Kalan katının kütlesi ise 28 gramdır.\nBuna göre X elementinin atom kütlesi nedir?\n(C=12, O=16)",
