        "solution": "Katı kütlesi 22 gram azaldıysa, bu uçup giden gazın (CO2) kütlesidir. Zaten soruda da oluşan gazın 22g olduğu verilmiş.\n22 gram CO2 = $22/44 = 0.5 \\ mol$.\nDemek ki tepkimede harcanan $XCO_3$ de 0.5 moldür.\nKalan katı (XO) = 28 gram. (Çünkü 0.5 mol XO oluştu).\n$0.5 \\ mol \\ XO = 28 \\ gram \\Rightarrow 1 \\ mol \\ XO = 56 \\ gram$.\n$X + 16 = 56 \\Rightarrow X = 40$. (Kalsiyum). (B)."
