        "question": "Eşit kütledeki Hidrojen ($H_2$) ve Oksijen ($O_2$) gazları kıvılcım çakılarak tam verimle tepkimeye sokulduğunda 36 gram su ($H_2O$) oluşuyor.\nBuna göre başlangıç karışımının kütlesi kaç gramdır?",
