        "solution": "I. bileşik: %40 X, %60 Y.\nII. bileşik: %50 X, %50 Y.\n\"Y kütleleri eşitlendiğinde\" dediği için Y'leri ortak bir sayıda (örneğin 300) eşitleyelim.\nI. bileşik (5 ile çarp): 200 X, 300 Y.\nII. bileşik (6 ile çarp): 300 X, 300 Y.\nY'ler 300 iken, X'ler arası oran (I / II) = $200 / 300 = 2/3$.\nBize I / II sorulmuş, 2/3 (A şıkkı).\n(Cevap anahtarına A yazılmalıdır, B demişim. 2/3). (A)."
