        "solution": "Kirlilik %40 ise, SAF kısmı %60'tır.\n500 gramın %60'ı = $500 \\times 0.6 = 300 \\ gram$ saf $CaCO_3$.\n$CaCO_3$ MA'sı = 100.\n$300 \\ gram = 3 \\ mol$.\nAyrışınca 1 molden 1 mol CO2 çıkar.\n3 molden 3 mol CO2 çıkar.\nHacim = $3 \\times 22.4 = 67.2 \\ Litre$. (B)."
