        "difficulty": "hard",
        "solution": "Tam yanma: $C + O_2 \\rightarrow CO_2$. (1 mol C için 1 mol O2 yani 32 gram O2 harcanır. m1=32).\nEksik yanma: $C + 1/2 O_2 \\rightarrow CO$. (1 mol C için 0.5 mol O2 yani 16 gram O2 harcanır. m2=16).\n$m_1 / m_2 = 32 / 16 = 2 / 1$. (B)."
