        "question": "$X_2Y_3$ bileşiğinde kütlece birleşme oranı $m_X / m_Y = 7/3$'tür.\nEşit kütledeki X ve Y elementlerinden en fazla 40 gram $XY_2$ bileşiği elde edildiğinde kapta artan elementin kütlesi kaç gramdır?",
