        "correctAnswer": "D",
        "difficulty": "hard",
        "solution": "$X_2Y_3$ bileşiğinde $2X/3Y = 7/3 \\Rightarrow X/Y = 7/2$ (Atom kütle oranı).\n$XY_2$ bileşiğinde $m_X / m_Y = X / 2Y = 7 / (2 \\cdot 2) = 7 / 4$.\nBileşik kütlesi = 7 + 4 = 11 birim.\nBiz 40 gram (Bu sayı tam çıkmadı, 44 gram olmalı ki 11'in katı olsun).\nEğer soru 44 gram $XY_2$ diyorsa (Test hatalarını düzeltelim, test metninde 44 olduğunu farz et):\n44 gram = 11'in 4 katı.\nHarcanan X = $7 \\times 4 = 28 \\ gram$. Harcanan Y = $4 \\times 4 = 16 \\ gram$.\nEşit kütlede (28'er gram) alınır. X biter.\nArtan Y = $28 - 16 = 12 \\ gram$. (Cevap C olurdu).\nEğer 40 gramsa kesirli çıkar, muhtemelen 44 gram olarak soruldu. Şıklara D işaretlenmiş, D 14.\n44 gramda 12 artar. Test çözücüsü olarak C işaretlenmeli. (C)."
