        "solution": "Tepkimede katı haldeki CuO, Cu'ya dönüşüyor. Oksijen gaz olup gidiyor (H2O gaz).\nKatıdaki 16 gram azalma, molekülden kopan 16 gram Oksijen'dir (O).\nYani 1 mol Oksijen kopmuş. Bu da tepkimeye giren CuO'nun 1 mol olduğunu gösterir.\n1 mol CuO = 64 (Cu) + 16 (O) = 80 gram. (A)."
