        "question": "Hava yastığı şişme mekanizmasında;\n$2NaN_3(k) \\rightarrow 2Na(k) + 3N_2(g)$\nTepkimesine ek olarak, oluşan sodyum metalinin zarar vermemesi için;\n$10Na + 2KNO_3 \\rightarrow K_2O + 5Na_2O + N_2(g)$\nikinci bir tepkime daha gerçekleşir ve fazladan $N_2$ üretilir.\nEğer sistemde 1 mol $NaN_3$ harcanırsa, YALNIZCA ikinci tepkimeden elde edilen $N_2$ gazı kaç moldür?\n(Zincirleme tepkime sorusudur).",
