        "question": "Eşit kütledeki $SO_2$ ve $O_2$ gazları tam verimle reaksiyona girerek $SO_3$ gazı oluşturuyor.\nTepkime tamamlandığında ortamda 24 gram Oksijen gazı arttığına göre, oluşan $SO_3$ gazı kaç gramdır?\n(S = 32, O = 16)",
