        "question": "Aynı koşullardaki (eşit hacimli) $H_2$ ve $N_2$ gazları birleşerek $NH_3$ gazını oluşturmaktadır.\nTepkime %100 verimle tamamlandığında kapta artan gaz hacminin, oluşan $NH_3$ gazı hacmine oranı kaçtır?\n(Denklem: $N_2 + 3H_2 \\rightarrow 2NH_3$)",
