        "difficulty": "hard",
        "solution": "Denklem: $1 N_2 + 3 H_2 \\rightarrow 2 NH_3$.\nEşit hacim: İkisinden de 3'er V (veya 3'er mol) alınsın.\nSınırlayıcı H2'dir (Tümü, 3V biter).\nN2'den 1V harcanır. Artan N2 = $3V - 1V = 2V$.\nOluşan NH3 = 2V.\nArtan Hacim (2V) / Oluşan Hacim (2V) = 1. (B)."
